--
-- Name: v_agents_pathogenes; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.v_agents_pathogenes AS
 SELECT path.agent_pathogene,
    count(DISTINCT f.id_cas) AS nombre_cas_suspects,
    sum(f.nombre_personnes_malades) AS total_malades,
    count(DISTINCT f.id_aliment) AS aliments_impliques,
    count(DISTINCT f.id_etablissement_dim) AS etablissements_impliques,
    round(avg(f.temperature_patient), 2) AS temperature_moyenne,
    round(avg(f.duree_symptomes_heures), 1) AS duree_moyenne_heures
   FROM (core.fait_intoxication f
     LEFT JOIN core.dim_pathogene path ON ((f.id_pathogene = path.id_pathogene)))
  WHERE ((path.agent_pathogene IS NOT NULL) AND ((path.agent_pathogene)::text <> ''::text))
  GROUP BY path.agent_pathogene
  ORDER BY (count(DISTINCT f.id_cas)) DESC;


ALTER VIEW analytics.v_agents_pathogenes OWNER TO postgres;

