--
-- Name: v_analyse_geographique; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.v_analyse_geographique AS
 SELECT loc.region,
    loc.ville,
    count(DISTINCT f.id_cas) AS nombre_cas,
    sum(f.nombre_personnes_exposees) AS total_exposes,
    sum(f.nombre_personnes_malades) AS total_malades,
    round(avg(f.taux_attaque), 2) AS taux_attaque_moyen,
    count(DISTINCT f.id_etablissement_dim) AS etablissements_touchees,
    sum(
        CASE
            WHEN ((sg.gravite)::text = 'Critique'::text) THEN 1
            ELSE 0
        END) AS cas_graves
   FROM ((core.fait_intoxication f
     JOIN core.dim_localisation loc ON ((f.id_localisation = loc.id_localisation)))
     LEFT JOIN core.dim_symptome_gravite sg ON ((f.id_symptome_gravite = sg.id_symptome_gravite)))
  GROUP BY loc.region, loc.ville
  ORDER BY (sum(f.nombre_personnes_malades)) DESC;


ALTER VIEW analytics.v_analyse_geographique OWNER TO postgres;

--
-- Name: v_analyse_gravite; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.v_analyse_gravite AS
 SELECT sg.symptome_principal,
    sg.gravite,
    count(DISTINCT f.id_cas) AS nombre_cas,
    sum(f.nombre_personnes_malades) AS total_malades,
    sum(
        CASE
            WHEN ((f.hospitalisation)::text = 'Oui'::text) THEN 1
            ELSE 0
        END) AS cas_hospitalises,
    round((((sum(
        CASE
            WHEN ((f.hospitalisation)::text = 'Oui'::text) THEN 1
            ELSE 0
        END))::numeric / (count(DISTINCT f.id_cas))::numeric) * (100)::numeric), 2) AS taux_hospitalisation_pct,
    round(avg(f.temperature_patient), 2) AS temperature_moyenne,
    round(avg(f.duree_symptomes_heures), 1) AS duree_moyenne_heures
   FROM (core.fait_intoxication f
     LEFT JOIN core.dim_symptome_gravite sg ON ((f.id_symptome_gravite = sg.id_symptome_gravite)))
  WHERE ((sg.symptome_principal IS NOT NULL) AND (sg.gravite IS NOT NULL))
  GROUP BY sg.symptome_principal, sg.gravite
  ORDER BY (count(DISTINCT f.id_cas)) DESC;


ALTER VIEW analytics.v_analyse_gravite OWNER TO postgres;

