--
-- Name: v_analyse_temporelle; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.v_analyse_temporelle AS
 SELECT t.annee,
    t.trimestre,
    t.mois,
        CASE t.mois
            WHEN 1 THEN 'Janvier'::text
            WHEN 2 THEN 'Février'::text
            WHEN 3 THEN 'Mars'::text
            WHEN 4 THEN 'Avril'::text
            WHEN 5 THEN 'Mai'::text
            WHEN 6 THEN 'Juin'::text
            WHEN 7 THEN 'Juillet'::text
            WHEN 8 THEN 'Août'::text
            WHEN 9 THEN 'Septembre'::text
            WHEN 10 THEN 'Octobre'::text
            WHEN 11 THEN 'Novembre'::text
            WHEN 12 THEN 'Décembre'::text
            ELSE NULL::text
        END AS nom_mois,
    t.saison,
    count(DISTINCT f.id_cas) AS nombre_cas,
    sum(f.nombre_personnes_malades) AS total_malades,
    round(avg(f.taux_attaque), 2) AS taux_attaque_mensuel
   FROM (core.fait_intoxication f
     JOIN core.dim_temps t ON ((f.id_temps = t.id_temps)))
  GROUP BY t.annee, t.trimestre, t.mois, t.saison
  ORDER BY t.annee DESC, t.mois DESC;


ALTER VIEW analytics.v_analyse_temporelle OWNER TO postgres;

