--

CREATE VIEW analytics.v_etablissements_impliques AS
 SELECT etab.nom_etablissement,
    etab.type_etablissement,
    loc.ville,
    loc.region,
    count(DISTINCT f.id_cas) AS nombre_intoxications,
    sum(f.nombre_personnes_malades) AS total_malades,
    round(avg(f.taux_attaque), 2) AS taux_attaque_moyen,
    sum(
        CASE
            WHEN ((f.inspection_effectuee)::text = 'Oui'::text) THEN 1
            ELSE 0
        END) AS inspections_effectuees,
    sum(
        CASE
            WHEN ((f.fermeture_etablissement)::text = 'Oui'::text) THEN 1
            ELSE 0
        END) AS fermetures,
    round((((sum(
        CASE
            WHEN ((f.fermeture_etablissement)::text = 'Oui'::text) THEN 1
            ELSE 0
        END))::numeric / (count(DISTINCT f.id_cas))::numeric) * (100)::numeric), 2) AS taux_fermeture_pct
   FROM ((core.fait_intoxication f
     LEFT JOIN core.dim_etablissement etab ON ((f.id_etablissement_dim = etab.id_etablissement_dim)))
     LEFT JOIN core.dim_localisation loc ON ((f.id_localisation = loc.id_localisation)))
  WHERE (etab.nom_etablissement IS NOT NULL)
  GROUP BY etab.nom_etablissement, etab.type_etablissement, loc.ville, loc.region
  ORDER BY (sum(f.nombre_personnes_malades)) DESC;


