--
-- Name: v_profil_patients; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.v_profil_patients AS
 SELECT pat.genre_patient,
    pat.groupe_age,
    count(DISTINCT f.id_cas) AS nombre_cas,
    round(avg(pat.age_patient), 1) AS age_moyen,
    sum(
        CASE
            WHEN ((f.hospitalisation)::text = 'Oui'::text) THEN 1
            ELSE 0
        END) AS cas_hospitalises,
    round(avg(f.temperature_patient), 2) AS temperature_moyenne,
    round(avg(f.duree_symptomes_heures), 1) AS duree_moyenne_symptomes_heures
   FROM (core.fait_intoxication f
     LEFT JOIN core.dim_patient pat ON ((f.id_patient_dim = pat.id_patient_dim)))
  WHERE ((pat.genre_patient IS NOT NULL) AND (pat.groupe_age IS NOT NULL))
  GROUP BY pat.genre_patient, pat.groupe_age
  ORDER BY (count(DISTINCT f.id_cas)) DESC;


