-- Name: v_tableau_bord_inspection; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.v_tableau_bord_inspection AS
 SELECT count(DISTINCT id_cas) AS total_cas,
    sum(
        CASE
            WHEN ((inspection_effectuee)::text = 'Oui'::text) THEN 1
            ELSE 0
        END) AS inspections_effectuees,
    round((((sum(
        CASE
            WHEN ((inspection_effectuee)::text = 'Oui'::text) THEN 1
            ELSE 0
        END))::numeric / (count(DISTINCT id_cas))::numeric) * (100)::numeric), 2) AS taux_inspection_pct,
    sum(
        CASE
            WHEN ((fermeture_etablissement)::text = 'Oui'::text) THEN 1
            ELSE 0
        END) AS etablissements_fermes,
    sum(
        CASE
            WHEN ((hospitalisation)::text = 'Oui'::text) THEN 1
            ELSE 0
        END) AS personnes_hospitalisees,
    count(DISTINCT
        CASE
            WHEN (anomalie = true) THEN id_cas
            ELSE NULL::character varying
        END) AS cas_avec_anomalie
   FROM core.fait_intoxication f;


